-- ============================================================
-- BAZA DANYCH - Zastosowanie SQL (2) (LibreOffice / OpenOffice Base)
-- Silnik: HSQLDB (wbudowany)
-- Schemat HR (regions, countries, locations, departments,
--             employees, jobs, job_history, job_grades)
-- Uwagi:
--   - literały dat: {d 'YYYY-MM-DD'}
--   - nazwy UPPER CASE (Base automatycznie konwertuje)
--   - UNIQUE nie działa → pominięto
--   - GENERATED BY DEFAULT AS IDENTITY → autoinkrementacja PK
--   - cykliczny FK EMPLOYEES↔DEPARTMENTS → ALTER TABLE
-- ============================================================


-- ============================================================
-- ZADANIE 1: Utworzenie tabel
-- Kolejność: REGIONS → COUNTRIES → LOCATIONS → JOBS →
--            EMPLOYEES (bez FK→DEPARTMENTS) →
--            DEPARTMENTS → ALTER EMPLOYEES ADD FK→DEPARTMENTS →
--            JOB_HISTORY → JOB_GRADES
-- ============================================================

CREATE TABLE REGIONS (
    REGION_ID INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    REGION_NAME VARCHAR(25)
);

CREATE TABLE COUNTRIES (
    COUNTRY_ID CHAR(2) PRIMARY KEY,
    COUNTRY_NAME VARCHAR(40),
    REGION_ID INTEGER,
    FOREIGN KEY (REGION_ID) REFERENCES REGIONS(REGION_ID)
);

CREATE TABLE LOCATIONS (
    LOCATION_ID INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    STREET_ADDRESS VARCHAR(25),
    POSTAL_CODE VARCHAR(12),
    CITY VARCHAR(30),
    STATE_PROVINCE VARCHAR(12),
    COUNTRY_ID CHAR(2),
    FOREIGN KEY (COUNTRY_ID) REFERENCES COUNTRIES(COUNTRY_ID)
);

CREATE TABLE JOBS (
    JOB_ID VARCHAR(10) PRIMARY KEY,
    JOB_TITLE VARCHAR(35),
    MIN_SALARY DECIMAL(10,2),
    MAX_SALARY DECIMAL(10,2)
);

CREATE TABLE EMPLOYEES (
    EMPLOYEE_ID INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    FIRST_NAME VARCHAR(20),
    LAST_NAME VARCHAR(25),
    EMAIL VARCHAR(25),
    PHONE_NUMBER VARCHAR(25),
    HIRE_DATE DATE,
    JOB_ID VARCHAR(10),
    SALARY DECIMAL(10,2),
    COMMISION_PCT DECIMAL(4,2),
    MANAGER_ID INTEGER,
    DEPARTMENT_ID INTEGER,
    FOREIGN KEY (JOB_ID) REFERENCES JOBS(JOB_ID),
    FOREIGN KEY (MANAGER_ID) REFERENCES EMPLOYEES(EMPLOYEE_ID)
);

CREATE TABLE DEPARTMENTS (
    DEPARTMENT_ID INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    DEPARTMENT_NAME VARCHAR(30),
    MANAGER_ID INTEGER,
    LOCATION_ID INTEGER,
    FOREIGN KEY (MANAGER_ID) REFERENCES EMPLOYEES(EMPLOYEE_ID),
    FOREIGN KEY (LOCATION_ID) REFERENCES LOCATIONS(LOCATION_ID)
);

ALTER TABLE EMPLOYEES ADD FOREIGN KEY (DEPARTMENT_ID) REFERENCES DEPARTMENTS(DEPARTMENT_ID);

CREATE TABLE JOB_HISTORY (
    EMPLOYEE_ID INTEGER,
    START_DATE DATE,
    END_DATE DATE,
    JOB_ID VARCHAR(10),
    DEPARTMENT_ID INTEGER,
    PRIMARY KEY (EMPLOYEE_ID, START_DATE),
    FOREIGN KEY (EMPLOYEE_ID) REFERENCES EMPLOYEES(EMPLOYEE_ID),
    FOREIGN KEY (JOB_ID) REFERENCES JOBS(JOB_ID),
    FOREIGN KEY (DEPARTMENT_ID) REFERENCES DEPARTMENTS(DEPARTMENT_ID)
);

CREATE TABLE JOB_GRADES (
    GRADE_LEVEL VARCHAR(2) PRIMARY KEY,
    LOWEST_SAL DECIMAL(10,2),
    HIGHEST_SAL DECIMAL(10,2)
);


-- ============================================================
-- ZADANIE 2: Wpisanie rekordów
-- Kolejność: REGIONS → COUNTRIES → LOCATIONS → JOBS →
--            EMPLOYEES (DEPARTMENT_ID=NULL, potem UPDATE) →
--            DEPARTMENTS (MANAGER_ID → istniejący EMPLOYEES) →
--            UPDATE EMPLOYEES SET DEPARTMENT_ID →
--            JOB_HISTORY → JOB_GRADES
-- ============================================================

